window.pwIdentity=function(scope){var i=state.identity,_s=scope||'all';var _me='<div class="pw-row">'+field('你的显示名称','pwUserName',i.user_name)+avatarField('你的头像','pwUserAvatar',i.user_avatar,i.avatar_shape)+'</div>';var _bot='<div class="pw-row">'+field('当前角色名称','pwAssistantName',i.assistant_name)+avatarField('当前角色头像','pwAssistantAvatar',i.assistant_avatar,i.avatar_shape)+'</div>';var _body=(_s==='bot')?_bot:(_s==='me')?_me:(_me+_bot);var _rd=(i.avatar_shape!=='circle');_body+='<div class="field pw-shape-field"><label>头像外形</label><div class="pw-shape-opts"><label class="pw-shape-opt'+(_rd?' is-on':'')+'"><input type="radio" name="pwAvatarShape" value="rounded"'+(_rd?' checked':'')+'><span class="pw-shape-glyph sq"></span><span class="pw-shape-name">圆角方形</span></label><label class="pw-shape-opt'+(_rd?'':' is-on')+'"><input type="radio" name="pwAvatarShape" value="circle"'+(_rd?'':' checked')+'><span class="pw-shape-glyph ci"></span><span class="pw-shape-name">圆形</span></label></div></div>';_body+='<p class="pw-hint">图片裁成方形并保留中心区域；GIF 动画保持原样。保存后当前会话的历史消息也会立刻换成新头像（专家消息保留各自的图标）；名称只影响之后发出的消息。</p>';var d=modal(_s==='me'?'我的资料':_s==='bot'?'当前角色':'名称与头像',_body,'<button class="btn primary" id="pwSaveIdentity">保存</button>');bindAvatar(d,'pwUserAvatar');bindAvatar(d,'pwAssistantAvatar');d.querySelectorAll('[name="pwAvatarShape"]').forEach(function(option){option.onchange=function(){if(!option.checked)return;d.querySelectorAll('.pw-shape-opt').forEach(function(o){o.classList.toggle('is-on',o.contains(option));});d.querySelectorAll('.pw-avatar-input .pw-avatar').forEach(function(preview){preview.classList.toggle('circle',option.value==='circle');preview.querySelector('img')?.classList.toggle('circle',option.value==='circle');});};});d.querySelector('#pwSaveIdentity').onclick=async function(){try{if(d.querySelector('input[type=file]:disabled'))throw Error('头像正在上传，请稍候');var patch={};var un=d.querySelector('#pwUserName'),ua=d.querySelector('#pwUserAvatar'),an=d.querySelector('#pwAssistantName'),aa=d.querySelector('#pwAssistantAvatar');if(un&&ua){patch.user_name=un.value;patch.user_avatar=ua.value;}if(an&&aa){patch.assistant_name=an.value;patch.assistant_avatar=aa.value;}patch.avatar_shape=d.querySelector('[name="pwAvatarShape"]:checked').value;await request('/preferences','PUT',{identity:patch});await reload();if(currentSession)loadSessionMessages(currentSession,false,true);close();}catch(e){fail(e);}};};
