async function bindExpert(e,newChat){await ready;if(newChat||!currentSession){saveDraft(currentSession);var s=await api('/api/sessions','POST',{});currentSession=s.id;_sessions.unshift(s);_openTabs.push(s.id);persistTabs();}await request('/session','PUT',{id:currentSession,expert_id:e?(e.id||e.slug):null});await reload();_selectedExpert=null;document.getElementById('chatComposer').hidden=false;_channelViewActive=false;renderSelectedExpertBar();renderSessionTabs();restoreDraft(currentSession);updateHeader();switchPage('chat');scrollChatToBottom();loadSessionMessages(currentSession);close();toast(e?'后续消息使用 '+(e.name||e.label):'后续消息使用默认助手');}
window.pwOpenRole=async function(){try{await experts();var d=modal('选择本会话角色','<p class="pw-hint">专家提供职责、方法和表达方式；共享当前环境的技能与工具，不切换全局 SOUL。已有消息保留原署名，选择只影响接下来的回复。</p><input id="pwRoleQuery" placeholder="搜索专家名称、专长…"><div class="pw-results" id="pwRoleList" style="margin-top:10px"></div>');function render(){var q=d.querySelector('#pwRoleQuery').value.toLowerCase();var list=expertList.filter(e=>((e.name||'')+' '+(e.desc||'')+' '+(e.scene||'')).toLowerCase().includes(q));var b=d.querySelector('#pwRoleList');b.innerHTML='<button class="pw-result" data-default="1">'+E(state.identity.assistant_avatar)+' '+E(state.identity.assistant_name)+'<small> · 默认角色</small></button>'+list.map((e,i)=>'<button class="pw-result" data-expert="'+i+'"><b>'+E(_wfEmoji(e.emoji))+' '+E(e.name)+'</b><p>'+E(e.desc||(e.prompt||'').slice(0,100))+'</p></button>').join('');b.querySelector('[data-default]').onclick=()=>bindExpert(null,false).catch(fail);b.querySelectorAll('[data-expert]').forEach(x=>x.onclick=()=>bindExpert(list[Number(x.dataset.expert)],false).catch(fail));}d.querySelector('#pwRoleQuery').oninput=render;render();}catch(e){fail(e);}};
