 const e=(await request('/experts/'+encodeURIComponent(id))).expert;
 const d=modal('专家设定 · '+e.name,field('名称','ee_name',e.name)+avatarField('头像','ee_emoji',e.emoji)+field('简介','ee_desc',e.desc)+'<div class="field"><label for="ee_prompt">专家职责与方法</label><textarea id="ee_prompt" rows="12"></textarea></div><div class="field"><label for="ee_quick">快速提问（每行一个）</label><textarea id="ee_quick" rows="4"></textarea></div><p class="pw-hint">保存后用于新选择的专家。已有会话、排队消息和讨论成员保留各自快照。技能与工具由环境提供。</p>','<button class="btn primary" id="ee_save">保存设定</button>');
 d.querySelector('#ee_prompt').value=e.prompt;d.querySelector('#ee_quick').value=(e.quick_prompts||[]).join('\n');bindAvatar(d,'ee_emoji');
 d.querySelector('#ee_save').onclick=async function(){this.disabled=true;try{if(d.querySelector('input[type=file]:disabled'))throw Error('头像正在上传');await request('/experts/'+encodeURIComponent(id),'PUT',{revision:e.revision,name:d.querySelector('#ee_name').value,emoji:d.querySelector('#ee_emoji').value,desc:d.querySelector('#ee_desc').value,prompt:d.querySelector('#ee_prompt').value,quick_prompts:d.querySelector('#ee_quick').value.split('\n')});close();await renderBuiltinExperts();toast('专家设定已保存');}catch(err){fail(err);}finally{this.disabled=false;}};
